from math import isqrt

def is_prime(n):
    if n < 2:
        return False
    for k in range(2, isqrt(n) + 1):   # was range(2, n - 1): correct but O(n)
        if n % k == 0:
            return False
    return True


def test_is_prime():
    primes = [2, 3, 5, 7, 11, 13, 97, 7919]
    for n in primes:
        assert is_prime(n) is True, f"{n} should be prime"

    composites = [-7, 0, 1, 4, 6, 9, 15, 25, 100, 7917]
    for n in composites:
        assert is_prime(n) is False, f"{n} should not be prime"

    print("all is_prime tests passed")


if __name__ == "__main__":
    test_is_prime()
```

